@Mod.EventBusSubscriber(modid="thaumcraft")
public final class ProgressionProbe {
 static void check(boolean b,String why){if(!b)throw new AssertionError(why);}
 static void run(ServerPlayer p){var l=p.level();var at=BookFlowProbe.P;for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)l.getChunk((at.getX()>>4)+x,z);p.setPos(Vec3.atCenterOf(at));p.getAbilities().invulnerable=true;
  for(var id:List.of("arcane/vis_battery","arcane/activator_rail","jar_brace","crucible/metal_purification_copper_ore","crucible/metal_purification_deepslate_copper_ore"))check(l.recipeAccess().getRecipes().stream().anyMatch(h->h.id().identifier().toString().equals("thaumcraft:"+id)),"New book recipe did not load: "+id);
  for(var entry:ResearchCatalog.ENTRIES)for(var stage:entry.stages())for(var r:java.util.stream.Stream.concat(stage.items().stream(),stage.crafts().stream()).toList())check(r.legacy().contains("enchanted_placeholder")||BuiltInRegistries.ITEM.get(Identifier.parse(r.id())).isPresent(),"Research requires absent item: "+entry.key()+" "+r.id());
  var triggers=ResearchCatalog.load("aspects.json").getAsJsonObject().getAsJsonObject("triggers");for(var key:triggers.getAsJsonObject("entities").keySet())check(BuiltInRegistries.ENTITY_TYPE.get(Identifier.parse(key)).isPresent(),"Trigger targets absent entity "+key);for(var key:triggers.getAsJsonObject("items").keySet())check(BuiltInRegistries.ITEM.get(Identifier.parse(key)).isPresent(),"Trigger targets absent item "+key);
  // Resources are supplied, but research starts empty and is never granted in this path.
  check(ResearchService.state(p).equals(KnowledgeState.EMPTY),"Fresh knowledge not empty");ResearchService.flag(p,"!gotcrystals");ResearchEvents.dream(p);var shelf=at.west(2);l.setBlockAndUpdate(shelf,Blocks.BOOKSHELF.defaultBlockState());p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(ArcaneContent.SALIS.get(),5));check(ArcaneContent.SALIS.get().useOn(BookFlowProbe.context(p,shelf))==InteractionResult.SUCCESS,"Salis book refused");ResearchService.openBook(p);check(ResearchService.knows(p,"FIRSTSTEPS@1"),"First Steps not started");l.setBlockAndUpdate(at,Blocks.CRAFTING_TABLE.defaultBlockState());check(ArcaneContent.SALIS.get().useOn(BookFlowProbe.context(p,at))==InteractionResult.SUCCESS,"Arcane table refused");check(ResearchService.advance(p,"FIRSTSTEPS"),"Crafted table did not advance First Steps");var table=(ArcaneWorkbenchEntity)l.getBlockEntity(at);BookFlowProbe.resetAura(l);BookFlowProbe.meter(table,1,true);var craft=new ArcaneMenu(68,p.getInventory(),table);craft.clicked(ArcaneMenu.RESULT,0,ContainerInput.PICKUP,p);check(craft.getCarried().is(ResearchContent.METER.get()),"Native meter output unavailable before completing First Steps");p.getInventory().add(craft.getCarried());craft.setCarried(ItemStack.EMPTY);
  for(var item:List.of(Items.DIAMOND_BLOCK,Items.GOLD_BLOCK,Items.IRON_BLOCK,Items.REDSTONE_BLOCK,Items.COAL_BLOCK,Items.GLOWSTONE,Items.BOOKSHELF,Items.CRAFTING_TABLE,Items.CHEST,Items.FURNACE,Items.WHEAT,Items.COOKED_BEEF,Items.BONE,Items.OAK_LOG,Items.GLASS,Items.WATER_BUCKET,Items.ENDER_PEARL,Items.BLAZE_ROD,Items.EMERALD_BLOCK,Items.LAPIS_BLOCK))ScanningService.observe(p,new ItemStack(item));check(ResearchService.advance(p,"FIRSTSTEPS")&&ResearchService.knows(p,"FIRSTSTEPS"),"Scanning/crafting cannot complete First Steps");check(ResearchService.advance(p,"UNLOCKALCHEMY")&&ResearchService.advance(p,"UNLOCKALCHEMY"),"Alchemy stage 2 blocked by observations");var cauldron=at.east(2);l.setBlockAndUpdate(cauldron,Blocks.CAULDRON.defaultBlockState());p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(ArcaneContent.SALIS.get(),2));check(ArcaneContent.SALIS.get().useOn(BookFlowProbe.context(p,cauldron))==InteractionResult.SUCCESS,"Crucible conversion blocked");check(ResearchService.advance(p,"UNLOCKALCHEMY"),"Crucible proof did not unlock nitor stage");var crucible=(AlchemyMachine)l.getBlockEntity(cauldron);l.setBlockAndUpdate(cauldron.below(),Blocks.MAGMA_BLOCK.defaultBlockState());crucible.water.fill(new net.minecraftforge.fluids.FluidStack(net.minecraft.world.level.material.Fluids.WATER,1000),net.minecraftforge.fluids.capability.IFluidHandler.FluidAction.EXECUTE);l.getServer().tickRateManager().setFrozen(false);for(int i=0;i<155;i++)crucible.serverTick();l.getServer().tickRateManager().setFrozen(true);for(int i=0;i<3;i++)check(crucible.process(new ItemStack(Items.COAL),p),"Crucible rejected fuel aspects");for(int i=0;i<12;i++)check(crucible.process(new ItemStack(Items.TORCH),p),"Crucible rejected light aspects");check(crucible.process(new ItemStack(Items.GLOWSTONE_DUST),p),"Nitor unavailable in its own prerequisite stage");check(ResearchService.advance(p,"UNLOCKALCHEMY")&&ResearchCatalog.categoryUnlocked(ResearchService.state(p),"ALCHEMY"),"Native nitor craft did not unlock Alchemy chapter");thaumcraft.Thaumcraft.LOGGER.info("PROGRESSION68_FRESH_ALCHEMY_OK: empty research, dream, book, table, native meter output, actual observations, heated crucible, nitor and chapter unlock without research grants");
  ScanningService.observe(p,new net.minecraft.world.entity.animal.golem.IronGolem(EntityTypes.IRON_GOLEM,l));ScanningService.observe(p,new thaumcraft.warp.WarpMonster(thaumcraft.warp.WarpCreatures.KNIGHT.get(),l,thaumcraft.warp.WarpMonster.Kind.KNIGHT));ScanningService.observe(p,new thaumcraft.eldritch.FireBat(thaumcraft.eldritch.EldritchContent.FIREBAT.get(),l));check(ResearchService.knows(p,"f_golem")&&ResearchService.knows(p,"!CrimsonCultist")&&ResearchService.knows(p,"!Firebat"),"Native discoveries did not match modern entity registry");var before=ResearchService.state(p);check(ResearchDiscovery.reconcile(before,false).points().equals(before.points()),"Discovery migration awarded duplicate knowledge");
  var saved=ResearchService.state(p);thaumcraft.persistence.PlayerWarpStore.write(p,new thaumcraft.persistence.PlayerWarpStore.State(1,25,5,0,30));var rites=thaumcraft.infusion.CuriosityContent.curio("rites");check(thaumcraft.infusion.CuriosityContent.study(p,rites)&&ResearchService.knows(p,"CrimsonRites")&&rites.isEmpty(),"Native rites study did not complete its real research");var current=ResearchDiscovery.reconcile(ResearchService.state(p),true);check(ResearchCatalog.knows(current,"WARP"),"Lasting warp did not discover WARP");KnowledgeStore.write(p,current);check(!ResearchService.canAdvance(p,ResearchCatalog.BY_KEY.get("WARP"))&&!ResearchService.canAdvance(p,ResearchCatalog.BY_KEY.get("CrimsonRites")),"Completed flag/study can be advanced again");var sanity=l.recipeAccess().getRecipes().stream().filter(r->r.id().identifier().toString().equals("thaumcraft:arcane/sanity_checker")).findFirst().orElseThrow().value();check(sanity instanceof ArcaneRecipe a&&a.research().equals("WARP"),"Sanity checker still has nonexistent research");
  var base=current.stage("SEALCOLLECT",ResearchCatalog.BY_KEY.get("SEALCOLLECT").stages().size()+1);KnowledgeStore.write(p,base);var menu=new ResearchMenu(68,p.getInventory());int index=ResearchCatalog.ENTRIES.indexOf(ResearchCatalog.BY_KEY.get("SEALCOLLECT"));check(!menu.addendumVisible(index,0),"Advanced seal addendum revealed without biothaumic mind");KnowledgeStore.write(p,base.stage("MINDBIOTHAUMIC",ResearchCatalog.BY_KEY.get("MINDBIOTHAUMIC").stages().size()+1));menu.broadcastChanges();check(menu.addendumVisible(index,0),"Completed biothaumic mind did not reveal advanced seal addendum");
  thaumcraft.Thaumcraft.LOGGER.info("PROGRESSION68_DISCOVERY_ADDENDA_OK: registered triggers, iron golem, cultist, firebat, real rites study, warp, sanity checker and conditional advanced seal addenda");
 }
 @SubscribeEvent public static void start(ServerStartedEvent e){if(!Set.of("progression","completion").contains(System.getProperty("thaumcraft.bookProbe","")))return;var l=e.getServer().overworld();e.getServer().tickRateManager().setFrozen(true);var p=new ServerPlayer(e.getServer(),l,new GameProfile(UUID.randomUUID(),"ProgressionProof"),ClientInformation.createDefault()){@Override public void sendSystemMessage(net.minecraft.network.chat.Component c,boolean overlay){}@Override protected ItemCooldowns createItemCooldowns(){return new ItemCooldowns();}};new net.minecraft.server.network.ServerGamePacketListenerImpl(e.getServer(),new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND),p,net.minecraft.server.network.CommonListenerCookie.createInitial(p.getGameProfile(),false)){@Override public void send(net.minecraft.network.protocol.Packet<?> packet){}@Override public void send(net.minecraft.network.protocol.Packet<?> packet,io.netty.channel.ChannelFutureListener listener){}};p.gameMode.changeGameModeForPlayer(GameType.SURVIVAL);run(p);if(System.getProperty("thaumcraft.bookProbe","").equals("completion"))BookCompletionProbe.run(p);thaumcraft.Thaumcraft.LOGGER.info("PROGRESSION68_NATIVE_OK");e.getServer().halt(false);}
}
